// TripQuest 的原創圖形：紙飛機、背包（Yolin 2026-10-27 核准；草圖 docs/sketches/原創圖形草圖.svg 的 A／B），
// 加上六隻吉祥物（2026-11-13；Yolin 看過第 5 版：「可以試著放進App」）。
// 原本這裡寫「就這兩個，不要加第三個」——那是吉祥物解禁之前的規定，2026-11-12 Yolin 解禁、11-13 同意放進 App，作廢。
// 吉祥物是「試著」放：整段在一個獨立的 commit，要拔就 revert 那一個 commit
// （背包的函式與樣式沒刪：拔掉時頁首換回 backpack() 就回到原樣）。
//
//   紙飛機（日期軸的標記，停在選中那一天上面、機頭朝右＝下一天）：兩個三角形＋一條折線。
//   背包（2026-11-13 以前的頁首識別；現在頁首放雪納瑞的頭，背包留著備用）：圓弧提把＋圓角矩形本體＋上蓋線＋前口袋。
//
// 紙飛機與背包為什麼跟任何授權角色都沒有關聯：只用三角形、圓角矩形、圓弧、直線這幾種幾何形，
// 沒有臉、不擬人；也沒有任何文字或商標。形狀是照草圖自己畫的座標，不是從任何圖庫或角色描下來的。
// 顏色不寫死：線條用 --text、色塊用 --primary／--accent／--ok（CSS 的 .gl-* 類別），深色與和紙各自套自己的值。
//
// 吉祥物（六隻平等；畫面上不寫名字；誰放哪裡見 MASCOT_SPOT）：雪納瑞、白兔、白熊、玄鳳鸚鵡、鷹、山雀。
// 原創性的檢查（把名字拿掉，會不會被認成某一隻特定角色；每隻跟同物種常見角色的明確不同處）見 docs/吉祥物原創性檢查.md。
// 圖是自己用通用的可愛畫法（大頭、短手腳、粗外框、腮紅）畫的座標，不是從任何角色、圖庫或參考圖描或量下來的。
// 正本就是下面 ART 的字串（產圖的程式在當時的工作暫存區、不在 repo；要改圖就改這裡）。
// 顏色寫在圖裡（吉祥物的毛色、衣服不跟主題變）；深色主題另外加白邊，見 mascot() 上面的說明。
//
// 全部純裝飾，一律 aria-hidden；意思由旁邊的字講（「第 N 天」、標題、「還沒有旅程」…）。
// 輸入全是本檔的常數字串（同 install.js 的圖示），不接任何外來資料。

const NS = 'http://www.w3.org/2000/svg';

function svg(viewBox, cls, inner, w, hgt) {
  const el = document.createElementNS(NS, 'svg');
  el.setAttribute('viewBox', viewBox);
  el.setAttribute('width', String(w));
  el.setAttribute('height', String(hgt));
  el.setAttribute('aria-hidden', 'true');
  el.setAttribute('focusable', 'false');
  el.setAttribute('class', cls);
  el.innerHTML = inner;
  return el;
}

export function paperPlane(w = 30) {
  return svg('-3 -3 62 52', 'gl gl-plane',
    '<polygon class="gl-paper" points="0,22 56,0 30,46"/>'
    + '<polygon class="gl-wing" points="30,46 26,30 56,0"/>'
    + '<line class="gl-fold" x1="26" y1="30" x2="0" y2="22"/>',
    w, Math.round(w * 52 / 62));
}

export function backpack(hgt = 26) {
  return svg('0 0 56 64', 'gl gl-pack',
    '<path class="gl-strap" d="M14 10 Q14 2 22 2 H34 Q42 2 42 10"/>'
    + '<rect class="gl-body" x="4" y="10" width="48" height="50" rx="14"/>'
    + '<path class="gl-flap" d="M4 26 Q28 36 52 26"/>'
    + '<rect class="gl-pocket" x="16" y="38" width="24" height="15" rx="5"/>',
    Math.round(hgt * 56 / 64), hgt);
}

// ---- 吉祥物 ----
// 每個出場處固定一隻（Yolin：六隻平等、次數差不多；雪納瑞放最重要的頁首）。這張表就是「誰在哪裡」的決定，改這裡就好。
export const MASCOT_SPOT = Object.freeze({
  header: 'schnauzer',   // 頁首標題左邊（只放頭，跟原本的背包一樣高 → 頁首高度不變）
  empty: 'bunny',        // 空白頁：「我的旅程」還沒有旅程（揮手打招呼）
  loading: 'hawk',       // 載入中：spinnerBox（讀邀請、整理回顧、查天氣；拿望遠鏡在找）
  done: 'cockatiel',     // 完成任務：加照片完成任務的慶祝畫面（打領結、頭冠翹起來）
  recap: 'bear',         // 行程回顧：最終回顧的標題上面
  settings: 'tit',       // 設定頁：「關於」那張卡
});

const MASCOT_VB = '-6 -6 212 252';   // 畫布 200×240，四邊各留 6：深色的白邊（外擴 5）才不會被裁掉
const HEAD_VB = '25 16 150 110';    // 頁首只裁雪納瑞的頭（v1.99.0 新頭含兩隻折耳：墨外框 x 31～169.25、y 21.75～120，四邊留 ≥ 5.75，深色白邊外擴 5 才不會被裁）
let rimSeq = 0;

// 深色主題的白邊：沿剪影外擴 5、塗白、墊在原圖下面（深底上黑外框才分得出輪廓）。
// 濾鏡寫成 SVG 的 filter 屬性、每一張的 id 都不同（同一頁有好幾張也不會互相指錯）；
// 和紙主題由 CSS 關掉（html[data-theme="washi"] .mc-fig { filter: none }——CSS 蓋得過 SVG 的屬性）。
// 地面陰影與動作線只在和紙畫：深底上幾乎看不到，白邊版本來就不畫（CSS 的 .mc-shadow／.mc-extra）。
function rimDefs(id) {
  return `<defs><filter id="${id}" x="-15%" y="-15%" width="130%" height="130%">`
    + '<feMorphology in="SourceAlpha" operator="dilate" radius="5" result="d"/><feFlood flood-color="#ffffff"/>'
    + '<feComposite in2="d" operator="in" result="w"/>'
    + '<feMerge><feMergeNode in="w"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>';
}

function figure(kind, viewBox, withGround, w, hgt, cls) {
  const a = ART[kind];
  if (!a) throw new Error('沒有這隻吉祥物：' + kind);
  const seq = ++rimSeq;
  const id = `tq-rim-${seq}`;
  // 圖裡的 id（裁切框）是 i0、i1…，每一張加上自己的流水號：同一頁放好幾張時，引用才不會指到別張的裁切框
  const pose = a.pose.replace(/(\bid="|url\(#)(i\d+)(?=[")])/g, `$1mc${seq}-$2`);
  const el = svg(viewBox, cls,
    rimDefs(id)
    + (withGround ? `<g class="mc-shadow">${a.shadow}</g>` : '')
    + `<g class="mc-fig" filter="url(#${id})">${pose}</g>`
    + (withGround && a.extra ? `<g class="mc-extra">${a.extra}</g>` : ''),
    w, hgt);
  el.setAttribute('data-mascot', kind);
  return el;
}

// 整隻（含地面陰影與動作線）。hgt 是畫面上的高度（px）。
// 注意：不要掛 .gl 類別——.gl 的樣式會把每一條線改成字色，吉祥物的顏色寫在圖裡。
export function mascot(kind, hgt = 96) {
  return figure(kind, MASCOT_VB, true, Math.round(hgt * 212 / 252), hgt, `gl-mascot mc-${kind}`);
}

// 頁首的頭（雪納瑞）：高度預設 26，跟原本的背包一樣
export function mascotHead(hgt = 26) {
  return figure(MASCOT_SPOT.header, HEAD_VB, false, Math.round(hgt * 150 / 110), hgt, 'gl-mascot gl-mascot-head');
}

// 圓形頭像（v1.95.0 吉祥物融入介面第一版）：從全身圖裁一塊正方形、裝進圓框。
// 用在任務頁進度條的前端（山雀）、行程分頁「行程｜回顧」選中那一格（鷹、熊）。
// 為什麼是圓框、不是直接裁頭：山雀是蛋形，頭跟身體沒有分界，直接裁底部是一條直的切口、兩角露出翅膀
// （規劃 docs/DESIGN_吉祥物融入介面.md 3.2 節）；圓框的邊有框線，看起來是刻意的。
// 裁切框（全身圖的畫布座標，200×240）：放大加格線看過，頭在圓的中間、圓的下緣切在脖子上。
const BADGE_VB = Object.freeze({
  tit: [36, 22, 128, 128],
  hawk: [40, 32, 120, 120],
  bear: [36, 30, 128, 128],
});
// 圓底與框線的顏色在 CSS（.mc-badge-bg、.mc-badge-ring）；圈裡不套深色白邊——框線已經把輪廓圈出來了。
export function mascotBadge(kind, px = 26) {
  const a = ART[kind], vb = BADGE_VB[kind];
  if (!a || !vb) throw new Error('沒有這隻的圓形頭像：' + kind);
  const seq = ++rimSeq;
  const [x, y, s] = vb, cx = x + s / 2, cy = y + s / 2, r = s / 2;
  const pose = a.pose.replace(/(\bid="|url\(#)(i\d+)(?=[")])/g, `$1mb${seq}-$2`);
  const el = svg(vb.join(' '), 'gl-mascot mc-badge',
    `<defs><clipPath id="mb${seq}-c"><circle cx="${cx}" cy="${cy}" r="${r - 1}"/></clipPath></defs>`
    + `<circle class="mc-badge-bg" cx="${cx}" cy="${cy}" r="${r}"/>`
    + `<g clip-path="url(#mb${seq}-c)"><g class="mc-fig">${pose}</g></g>`
    + `<circle class="mc-badge-ring" cx="${cx}" cy="${cy}" r="${r - 1}"/>`,
    px, px);
  el.setAttribute('data-mascot', kind);
  return el;
}

// ---- 吉祥物的動作（v1.85.0；Yolin 看了 v1.83.0 完成任務那一刻的動畫：「效果不錯，推廣到其他時刻」，核過哪個時刻哪隻、什麼動作那張表）----
// 規矩：只動 transform 與 opacity；減少動態效果就完全不動（停在靜止圖）；除了載入中，都只動一次、動完停回靜止圖的位置。
// 這裡只負責把圖拆成會動的幾層、掛上 class；動作的時間與角度在 css/style.css（.mc-move、.pk-cheer 那一段）。
// 探頭圖（js/peeks.js 的 cheer()）也用這裡的三個函式。

// 減少動態效果：系統設定或設定頁的開關（js/prefs.js 兩個都看，結果放在 <html> 的 reduce-motion）。cheer() 與 moveMascot() 共用這一個判斷。
export function reducedMotion() {
  return document.documentElement.classList.contains('reduce-motion');
}

function gEl(attrs) {
  const x = document.createElementNS(NS, 'g');
  for (const [k, v] of Object.entries(attrs)) x.setAttribute(k, v);
  return x;
}
// 一個元素包成繞 pivot 動的一層：g[translate(pivot)] > g.cls > g[translate(-pivot)] > 原元素。
// 外層已經平移到 pivot，所以 CSS 轉的原點寫 0 0（transform-box: view-box）。回傳會動的那一層（g.cls）。
export function pivotWrap(x, [px, py], cls) {
  const outer = gEl({ transform: `translate(${px} ${py})` }), mid = gEl({ class: cls }), inner = gEl({ transform: `translate(${-px} ${-py})` });
  x.replaceWith(outer);
  inner.append(x); mid.append(inner); outer.append(mid);
  return mid;
}
// 一個零件包成會動的一層：root 底下 transform 屬性正好是 tf 的每一個元素各包一次（同一個零件常分好幾段畫——外框、底色、亮面——
// 中間夾著別的部位，不能整包成一個 g，只能一段一段包；每一段套同一個動畫，看起來就是整塊一起轉）。
// 回傳包了幾段：0＝圖改過、對不上，那個零件就不動（不會動錯地方）。
export function wrapPart(root, tf, pivot, cls) {
  const hits = root ? [...root.querySelectorAll('[transform]')].filter((x) => x.getAttribute('transform') === tf) : [];
  for (const x of hits) pivotWrap(x, pivot, cls);
  return hits.length;
}

// 全身吉祥物（mascot()）每一隻的動作；在哪裡呼叫就是哪個時刻動：
//   bunny 空白頁「還沒有旅程」：舉著的那隻手（肩膀 128,146）揮兩下，揮動線跟著一閃一閃（揮動線只在和紙畫）
//   bear 最終回顧：從下面淡入、跳出來
//   hawk 載入中：拿望遠鏡左右慢慢看（整隻繞腳底轉一點點），等待時一直重複——只有這一隻會重複
// 頁首的頭（雪納瑞）、設定頁的山雀不動（那張表）；完成任務那一隻是探頭圖，見 js/peeks.js。
// 解鎖新徽章的玄鳳（v1.85.0～v1.94.0 原地彈跳兩下）v1.95.0 改成從「太棒了」按鈕上緣探頭（js/addphoto.js 的 showNewBadges），
// 彈跳這一條沒有別的地方用，一起拿掉（留著就是一段永遠走不到的程式）。
// part＝要揮的那隻手（同 wrapPart）；body＝要整塊一起動的幾層（包成一個 g.mc-body；動畫放在圖裡面，<svg> 本身的框不動，排版不跳）；
// pivot＝整塊轉的原點（鷹的腳底）。
const MOVES = Object.freeze({
  bunny: { move: 'wave', part: { tf: 'translate(128 146) rotate(-122)', pivot: [128, 146], cls: 'pk-wave-r' }, lines: true },
  bear: { move: 'popin', body: ['.mc-shadow', '.mc-fig', '.mc-extra'] },
  hawk: { move: 'look', body: ['.mc-fig', '.mc-extra'], pivot: [100, 228] },
});
export const MOVE_KINDS = Object.freeze(Object.keys(MOVES));
// 讓一張 mascot() 動起來；回傳有沒有動。減少動態效果、沒登記動作的那幾隻、圖對不上：不動，停在靜止圖。
export function moveMascot(el) {
  if (!el || reducedMotion()) return false;
  const m = MOVES[el.getAttribute('data-mascot')];
  if (!m) return false;
  if (m.part && !wrapPart(el.querySelector('.mc-fig'), m.part.tf, m.part.pivot, m.part.cls)) return false;   // 揮的那隻手對不上：寧可不動
  if (m.lines) el.querySelector('.mc-extra')?.classList.add('pk-wave-lines');
  if (m.body) {
    const kids = m.body.map((s) => el.querySelector(`:scope > ${s}`)).filter(Boolean);
    if (!kids.length) return false;
    const body = gEl({ class: 'mc-body' });
    kids[0].before(body);
    body.append(...kids);
    if (m.pivot) pivotWrap(body, m.pivot, 'mc-look');
  }
  el.classList.add('mc-move', `mc-move-${m.move}`);
  return true;
}

// ---- 拍照圖示（2026-11-13 第四段；Yolin：「甚至拍照那些圖示也可以一起換掉」）----
// 「拍照」「從相簿選」兩顆按鈕：**功能的形狀當主體**（相機、一張相片），吉祥物只從邊上探出來——
// 相機後面是雪納瑞的頭頂、折耳、眉毛，兩隻手扶著機身；相片後面冒出白兔的兩隻耳朵。
// 按鈕大小不變（任務列 46×46、展開後的大按鈕照舊），圖示是裝飾、aria-hidden：意思由按鈕自己的 aria-label／字講。
// 圖裡沒有 id：每一列任務都有一組，同一頁幾十個也不會互相指錯。畫布 64×64。
export function photoIcon(kind, size = 30) {
  const a = ICON[kind];
  if (!a) throw new Error('沒有這個圖示：' + kind);
  const el = svg('0 0 64 64', `gl-icon gl-icon-${kind}`, a, size, size);
  el.setAttribute('data-icon', kind);
  return el;
}

